from datetime import datetime

import pytest
from isoduration import add_duration


class TestBasicComponents:
    """Test individual duration components."""

    def test_years_single(self):
        assert add_duration(datetime(2020, 2, 29), "P1Y") == datetime(2021, 2, 28)

    def test_years_multiple(self):
        assert add_duration(datetime(2020, 1, 15), "P5Y") == datetime(2025, 1, 15)

    def test_months_single(self):
        assert add_duration(datetime(2024, 1, 31), "P1M") == datetime(2024, 2, 29)

    def test_months_multiple(self):
        assert add_duration(datetime(2024, 1, 15), "P13M") == datetime(2025, 2, 15)

    def test_weeks_single(self):
        assert add_duration(datetime(2025, 1, 1), "P1W") == datetime(2025, 1, 8)

    def test_weeks_multiple(self):
        assert add_duration(datetime(2025, 1, 1), "P3W") == datetime(2025, 1, 22)

    def test_days_single(self):
        assert add_duration(datetime(2025, 3, 10), "P1D") == datetime(2025, 3, 11)

    def test_days_multiple(self):
        assert add_duration(datetime(2025, 3, 10), "P10D") == datetime(2025, 3, 20)

    def test_hours_single(self):
        assert add_duration(datetime(2025, 3, 10, 5), "PT1H") == datetime(2025, 3, 10, 6)

    def test_hours_multiple(self):
        assert add_duration(datetime(2025, 3, 10, 5), "PT25H") == datetime(2025, 3, 11, 6)

    def test_minutes_single(self):
        assert add_duration(datetime(2025, 3, 10, 5, 0), "PT1M") == datetime(2025, 3, 10, 5, 1)

    def test_minutes_multiple(self):
        assert add_duration(datetime(2025, 3, 10, 5, 0), "PT90M") == datetime(2025, 3, 10, 6, 30)

    def test_seconds_single(self):
        assert add_duration(datetime(2025, 3, 10, 5, 0, 0), "PT1S") == datetime(2025, 3, 10, 5, 0, 1)

    def test_seconds_multiple(self):
        assert add_duration(datetime(2025, 3, 10, 5, 0, 0), "PT90S") == datetime(2025, 3, 10, 5, 1, 30)


class TestCombinations:
    """Test combinations of multiple components."""

    def test_years_and_months(self):
        assert add_duration(datetime(2024, 1, 31), "P1Y1M") == datetime(2025, 2, 28)

    def test_years_months_and_days(self):
        assert add_duration(datetime(2024, 1, 31), "P1Y1M5D") == datetime(2025, 3, 5)

    def test_years_months_days_and_time(self):
        assert add_duration(datetime(2024, 1, 31, 10, 30, 45), "P1Y1M5DT2H15M30S") == datetime(2025, 3, 5, 12, 46, 15)

    def test_months_and_days(self):
        assert add_duration(datetime(2024, 1, 15), "P2M10D") == datetime(2024, 3, 25)

    def test_days_and_time(self):
        assert add_duration(datetime(2025, 3, 10, 8, 30, 15), "P5DT3H45M20S") == datetime(2025, 3, 15, 12, 15, 35)

    def test_hours_minutes_seconds(self):
        assert add_duration(datetime(2025, 3, 10, 10, 30, 30), "PT2H30M45S") == datetime(2025, 3, 10, 13, 1, 15)


class TestMonthEndHandling:
    """Test month-end day adjustment when target month is shorter."""

    def test_jan_31_plus_1_month_to_feb_leap_year(self):
        assert add_duration(datetime(2024, 1, 31), "P1M") == datetime(2024, 2, 29)

    def test_jan_31_plus_1_month_to_feb_non_leap_year(self):
        assert add_duration(datetime(2025, 1, 31), "P1M") == datetime(2025, 2, 28)

    def test_march_31_plus_1_month_to_april(self):
        assert add_duration(datetime(2024, 3, 31), "P1M") == datetime(2024, 4, 30)

    def test_may_31_plus_1_month_to_june(self):
        assert add_duration(datetime(2024, 5, 31), "P1M") == datetime(2024, 6, 30)

    def test_multiple_months_crossing_feb(self):
        assert add_duration(datetime(2024, 1, 31), "P2M") == datetime(2024, 3, 31)

    def test_many_months_crossing_feb_leap(self):
        assert add_duration(datetime(2024, 1, 31), "P13M") == datetime(2025, 2, 28)

    def test_negative_month_to_shorter_month(self):
        assert add_duration(datetime(2024, 3, 31), "-P1M") == datetime(2024, 2, 29)

    def test_leap_year_feb_29_plus_1_year(self):
        assert add_duration(datetime(2024, 2, 29), "P1Y") == datetime(2025, 2, 28)

    def test_leap_year_feb_29_plus_4_years(self):
        assert add_duration(datetime(2024, 2, 29), "P4Y") == datetime(2028, 2, 29)


class TestNegativeDurations:
    """Test negative durations with - prefix."""

    def test_negative_days(self):
        assert add_duration(datetime(2025, 3, 10), "-P3D") == datetime(2025, 3, 7)

    def test_negative_months(self):
        assert add_duration(datetime(2024, 3, 31), "-P1M") == datetime(2024, 2, 29)

    def test_negative_years(self):
        assert add_duration(datetime(2025, 3, 15), "-P1Y") == datetime(2024, 3, 15)

    def test_negative_hours(self):
