class TestFractionalComponents:
    """Test fractional parts using . and , as decimal separators."""

    def test_fractional_seconds_dot(self):
        assert add_duration(datetime(2025, 3, 10, 5, 0, 0), "PT1.5S") == datetime(2025, 3, 10, 5, 0, 1, 500000)

    def test_fractional_seconds_comma(self):
        assert add_duration(datetime(2025, 3, 10, 5, 0, 0), "PT1,5S") == datetime(2025, 3, 10, 5, 0, 1, 500000)

    def test_fractional_minutes_dot(self):
        assert add_duration(datetime(2025, 3, 10, 5, 0, 0), "PT1.5M") == datetime(2025, 3, 10, 5, 1, 30)

    def test_fractional_minutes_comma(self):
        assert add_duration(datetime(2025, 3, 10, 5, 0, 0), "PT1,5M") == datetime(2025, 3, 10, 5, 1, 30)

    def test_fractional_hours_dot(self):
        assert add_duration(datetime(2025, 3, 10, 5, 0, 0), "PT1.5H") == datetime(2025, 3, 10, 6, 30, 0)

    def test_fractional_hours_comma(self):
        assert add_duration(datetime(2025, 3, 10, 5, 0, 0), "PT1,5H") == datetime(2025, 3, 10, 6, 30, 0)

    def test_fractional_days_dot(self):
        assert add_duration(datetime(2025, 3, 10), "P1.5D") == datetime(2025, 3, 11, 12, 0, 0)

    def test_fractional_days_comma(self):
        assert add_duration(datetime(2025, 3, 10), "P1,5D") == datetime(2025, 3, 11, 12, 0, 0)

    def test_fractional_weeks_dot(self):
        assert add_duration(datetime(2025, 1, 1), "P1.5W") == datetime(2025, 1, 11, 12, 0, 0)

    def test_fractional_weeks_comma(self):
        assert add_duration(datetime(2025, 1, 1), "P1,5W") == datetime(2025, 1, 11, 12, 0, 0)

    def test_fractional_subsecond_precision(self):
        result = add_duration(datetime(2025, 3, 10), "P0.0001D")
        # 0.0001 days = 8.64 seconds
        assert result.microsecond == 640000

    def test_fractional_leading_zero(self):
        assert add_duration(datetime(2025, 3, 10), "P0.5D") == datetime(2025, 3, 10, 12, 0, 0)

    def test_fractional_multiple_decimal_places(self):
        result = add_duration(datetime(2025, 3, 10), "P1.123D")
        # 0.123 days = 2.952 hours = 2 hours 57 minutes 7.2 seconds
        # Verify within microsecond precision
        expected = datetime(2025, 3, 11, 2, 57, 7, 200000)
        assert abs((result - expected).total_seconds()) < 0.000001


