class TestApplicationOrder:
    """Test that duration parts are applied in the correct order."""

    def test_order_months_before_days(self):
        # 2024-01-31 + 1 month (to 2024-02-29) + 2 days = 2024-03-02
        # NOT 2024-02-02 + 1 month
        result = add_duration(datetime(2024, 1, 31), "P1M2D")
        assert result == datetime(2024, 3, 2)

    def test_order_negative_months_before_days(self):
        # 2024-03-01 - 1 month (to 2024-02-01) - 1 day = 2024-01-31
        result = add_duration(datetime(2024, 3, 1), "-P1M1D")
        assert result == datetime(2024, 1, 31)

    def test_order_months_before_time(self):
        # Months are applied, then time components
        result = add_duration(datetime(2024, 1, 31, 10, 0), "P1M2DT5H")
        assert result == datetime(2024, 3, 4, 15, 0)


class TestBoundaryConditions:
    """Test boundary conditions and edge cases."""

    def test_start_of_year(self):
        assert add_duration(datetime(2025, 1, 1), "P1D") == datetime(2025, 1, 2)

    def test_end_of_year(self):
        assert add_duration(datetime(2025, 12, 31), "P1D") == datetime(2026, 1, 1)

    def test_midnight(self):
        assert add_duration(datetime(2025, 3, 10, 0, 0, 0), "PT23H59M59S") == datetime(2025, 3, 10, 23, 59, 59)

    def test_just_before_midnight(self):
        assert add_duration(datetime(2025, 3, 10, 23, 59, 59), "PT1S") == datetime(2025, 3, 11, 0, 0, 0)

    def test_leap_year_february(self):
        assert add_duration(datetime(2024, 2, 1), "P28D") == datetime(2024, 2, 29)

    def test_non_leap_year_february(self):
        assert add_duration(datetime(2025, 2, 1), "P27D") == datetime(2025, 2, 28)

    def test_zero_duration(self):
        # 0 of any component should leave datetime unchanged
        # But at least one component is required by spec
        pass

    def test_large_number_of_years(self):
        result = add_duration(datetime(2000, 1, 1), "P100Y")
        assert result == datetime(2100, 1, 1)

    def test_large_number_of_months(self):
        result = add_duration(datetime(2000, 1, 1), "P120M")
        assert result == datetime(2010, 1, 1)

    def test_very_large_seconds(self):
        result = add_duration(datetime(2025, 1, 1), "PT1000000S")
        # 1000000 seconds ≈ 11.57 days
        assert result > datetime(2025, 1, 11)

    def test_datetime_min_plus_duration(self):
        # datetime.min is year 1
        result = add_duration(datetime(1, 1, 1), "P1D")
        assert result == datetime(1, 1, 2)

    def test_datetime_near_max(self):
        # datetime.max is year 9999
        result = add_duration(datetime(9999, 12, 30), "P1D")
        assert result == datetime(9999, 12, 31)

    def test_overflow_raises_error(self):
        # datetime.max is 9999-12-31
        with pytest.raises(ValueError):
            add_duration(datetime(9999, 12, 31), "P1D")

    def test_underflow_raises_error(self):
        # datetime.min is year 1-01-01
        with pytest.raises(ValueError):
            add_duration(datetime(1, 1, 1), "-P1D")


class TestLeapYears:
    """Test handling of leap years."""

    def test_2000_is_leap_year(self):
        assert add_duration(datetime(2000, 2, 28), "P1D") == datetime(2000, 2, 29)

    def test_1900_is_not_leap_year(self):
        assert add_duration(datetime(1900, 2, 28), "P1D") == datetime(1900, 3, 1)

    def test_2100_is_not_leap_year(self):
        assert add_duration(datetime(2100, 2, 28), "P1D") == datetime(2100, 3, 1)

    def test_2024_is_leap_year(self):
        assert add_duration(datetime(2024, 2, 28), "P1D") == datetime(2024, 2, 29)

    def test_2025_is_not_leap_year(self):
        assert add_duration(datetime(2025, 2, 28), "P1D") == datetime(2025, 3, 1)


