class TestMicrosecondPrecision:
    """Test microsecond precision for fractional parts."""

    def test_half_microsecond_rounds(self):
        # 0.0000005 seconds should round to 1 microsecond
        result = add_duration(datetime(2025, 3, 10), "PT0.0000005S")
        # This depends on rounding rules: round to nearest
        assert result.microsecond in [0, 1]

    def test_fractional_precision(self):
        result = add_duration(datetime(2025, 3, 10), "PT0.123456S")
        # 0.123456 seconds = 123456 microseconds
        assert result.microsecond == 123456

    def test_fractional_precision_rounding(self):
        result = add_duration(datetime(2025, 3, 10), "PT0.1234567S")
        # 0.1234567 seconds = 123456.7 microseconds, should round to 123457
        assert result.microsecond == 123457


class TestComplexScenarios:
    """Test complex real-world scenarios."""

    def test_add_one_year_to_leap_day(self):
        assert add_duration(datetime(2024, 2, 29), "P1Y") == datetime(2025, 2, 28)

    def test_add_four_years_to_leap_day(self):
        assert add_duration(datetime(2024, 2, 29), "P4Y") == datetime(2028, 2, 29)

    def test_contract_duration_1_year_1_month(self):
        assert add_duration(datetime(2025, 2, 28), "P1Y1M") == datetime(2026, 3, 28)

    def test_subtract_across_multiple_months(self):
        result = add_duration(datetime(2024, 5, 31), "-P2M")
        assert result == datetime(2024, 3, 31)

    def test_full_cycle_add_and_negative(self):
        start = datetime(2024, 1, 15, 10, 30, 45)
        duration_str = "P1Y2M3DT4H5M6S"
        forward = add_duration(start, duration_str)
        # Applying negative should return to start (within microsecond precision)
        backward = add_duration(forward, "-" + duration_str)
        assert backward == start

    def test_fractional_day_with_months(self):
        result = add_duration(datetime(2024, 1, 31), "P1M0.5D")
        # 2024-01-31 + 1 month = 2024-02-29 + 0.5 days = 2024-02-29 12:00:00
        assert result == datetime(2024, 2, 29, 12, 0, 0)

    def test_very_long_duration(self):
        result = add_duration(datetime(2000, 1, 1), "P9999Y")
        # Should not overflow datetime range
        assert result == datetime(10999, 1, 1)

from datetime import datetime, timedelta

import pytest
